                LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: Layout.isTablet ? 5 : 2)) {
                    ForEach(0..<30, id: \.self) { _ in Color.gray.aspectRatio(2/3, contentMode: .fit) }
                }
            }
            .padding(.top, Layout.topInset)
        }
        .ignoresSafeArea()
    }
}

